    let kernel_rev = map (\i -> kernel[k - 1 - i]) (iota k)
    in map (\i -> reduce (+) 0.0f64 (map2 (*) (signal[i:i+k]) kernel_rev)) (iota (n - k + 1))

  def moving_average [n] (arr: [n]f64) (window: i64) : []f64 =
    if window <= 0 || window > n then replicate 0 0.0f64 else
    map (\i -> reduce (+) 0.0f64 (arr[i:i+window]) / f64.i64 window) (iota (n - window + 1))

  def exponential_moving_average [n] (arr: [n]f64) (alpha: f64) : [n]f64 =
    if n == 0 then copy arr else
    let clamped_alpha = f64.max 0.0f64 (f64.min 1.0f64 alpha)
    in scan (\acc x -> clamped_alpha * x + (1.0f64 - clamped_alpha) * acc) arr[0] arr

  def find_peaks [n] (arr: [n]f64) (threshold: f64) : []i64 =
    if n < 3 then replicate 0 0i64 else
    let is_peak = map (\i ->
      let val = arr[i+1]
      in val >= threshold && val > arr[i] && val > arr[i+2]
    ) (iota (n - 2))
    let indices = map (\i -> if is_peak[i] then i + 1 else -1) (iota (n - 2))
    in filter (\x -> x != -1) indices
